// src/config/real-forms.ts
var CATALOG = species_forms_catalog_v1_default;
var BY_DEX = new Map(CATALOG.species.map((row) => [row.dex, row]));
var CATALOG_RULES = CATALOG.rules;
var CATALOG_VERSION = CATALOG.version;
var CATALOG_SPECIES_COUNT = CATALOG.species.length;

// src/lib/species.ts
var OWNER_RE = new RegExp(OWNER_POSSESSIVE_PATTERN, "i");

// src/lib/pokedex.ts
var DEX = pokedex_default;
function getSpeciesByDex(dex) {
  return DEX.find((entry) => entry.n === dex);
}

// src/lib/fetchSpeciesPrints.ts
var API_BASE = "https://api.pokemontcg.io/v2";
var PAGE_SIZE = 250;
var USER_AGENT = "Nomekop/0.1 (+https://github.com/errix/Nomekop)";
var SELECT = [
  "id",
  "name",
  "supertype",
  "subtypes",
  "types",
  "number",
  "artist",
  "rarity",
  "nationalPokedexNumbers",
  "set",
  "images",
  "tcgplayer"
].join(",");
async function fetchPage(query, page, apiKey) {
  const url = new URL(`${API_BASE}/cards`);
  url.searchParams.set("q", query);
  url.searchParams.set("page", String(page));
  url.searchParams.set("pageSize", String(PAGE_SIZE));
  url.searchParams.set("orderBy", "set.releaseDate,number");
  url.searchParams.set("select", SELECT);
  const headers = {
    Accept: "application/json",
    "User-Agent": USER_AGENT
  };
  if (apiKey) headers["X-Api-Key"] = apiKey;
  let lastError = "unknown error";
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const response = await fetch(url, { headers });
    if (response.ok) return await response.json();
    lastError = `pokemontcg.io ${response.status} ${response.statusText}`;
    if (![429, 500, 502, 503].includes(response.status) || attempt === 3) {
      throw new Error(lastError);
    }
    await new Promise((resolve) => setTimeout(resolve, 400 * 2 ** attempt));
  }
  throw new Error(lastError);
}
function mockResult(dex, reason) {
  const species = getSpeciesByDex(dex);
  const prints = filterSpeciesArtForward(MOCK_CARDS, dex);
  return {
    source: "mock",
    dex,
    speciesName: species?.name ?? `Dex ${dex}`,
    query: luceneDexQuery(dex),
    keyUsed: false,
    totalFromApi: prints.length,
    prints,
    warning: `${reason} Showing sample prints so you can still verify the filter and UI.`
  };
}
function sortPrints(cards) {
  return [...cards].sort((a, b) => {
    const da = a.set?.releaseDate ?? "";
    const db = b.set?.releaseDate ?? "";
    if (da !== db) return db.localeCompare(da);
    return (a.number ?? "").localeCompare(b.number ?? "", void 0, { numeric: true });
  });
}
async function fetchSpeciesPrints(dex, apiKey = "") {
  const species = getSpeciesByDex(dex);
  const speciesName = species?.name ?? `Dex ${dex}`;
  const query = luceneDexQuery(dex);
  try {
    const first = await fetchPage(query, 1, apiKey);
    const all = [...first.data ?? []];
    const total = first.totalCount ?? all.length;
    const pages = Math.max(1, Math.ceil(total / PAGE_SIZE));
    for (let page = 2; page <= pages; page += 1) {
      const next = await fetchPage(query, page, apiKey);
      all.push(...next.data ?? []);
    }
    const prints = sortPrints(filterSpeciesArtForward(all, dex));
    return {
      source: "live",
      dex,
      speciesName,
      query,
      keyUsed: Boolean(apiKey),
      totalFromApi: total,
      prints
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown API error";
    const keyHint = apiKey ? "" : " POKEMONTCG_API_KEY is unset (optional free key from https://dev.pokemontcg.io).";
    return mockResult(dex, `Live pokemontcg.io lookup failed (${message}).${keyHint}`);
  }
}

// src/server/handleCardsRequest.ts
async function handleCardsRequest(requestUrl, apiKey) {
  try {
    const url = new URL(requestUrl, "http://nomekop.local");
    const dex = Number(url.searchParams.get("dex"));
    if (!Number.isInteger(dex) || dex < 1 || dex > 1025) {
      return {
        status: 400,
        body: { error: "Pass a National Pok\xE9dex number as ?dex=52" }
      };
    }
    const result = await fetchSpeciesPrints(dex, apiKey);
    return { status: 200, body: result };
  } catch (error) {
    const message = error instanceof Error ? error.message : "Cards lookup failed";
    return { status: 500, body: { error: message } };
  }
}
function jsonHeaders() {
  return {
    "content-type": "application/json; charset=utf-8",
    "cache-control": "public, max-age=60"
  };
}

// src/server/vercelCards.ts
function readApiKey() {
  return process.env.POKEMONTCG_API_KEY ?? "";
}
function requestUrlFrom(input) {
  if (typeof Request !== "undefined" && input instanceof Request) {
    return input.url;
  }
  const nodeReq = input;
  const dexParam = nodeReq.query?.dex;
  const dex = Array.isArray(dexParam) ? dexParam[0] : dexParam;
  return nodeReq.url ?? `/api/cards?dex=${dex ?? ""}`;
}
async function cardsPayload(requestUrl) {
  try {
    return await handleCardsRequest(requestUrl, readApiKey());
  } catch (error) {
    const message = error instanceof Error ? error.message : "Cards lookup failed";
    return { status: 500, body: { error: message } };
  }
}
function asJsonResponse(status, body) {
  return new Response(JSON.stringify(body), { status, headers: jsonHeaders() });
}
function isNodeResponse(value) {
  return typeof value === "object" && value !== null && typeof value.status === "function" && typeof value.setHeader === "function" && typeof value.json === "function";
}
async function GET(request) {
  const { status, body } = await cardsPayload(request.url);
  return asJsonResponse(status, body);
}
async function handler(req, res) {
  const { status, body } = await cardsPayload(requestUrlFrom(req));
  if (isNodeResponse(res)) {
    try {
      for (const [key, value] of Object.entries(jsonHeaders())) {
        res.setHeader(key, value);
      }
      res.status(status).json(body);
      return;
    } catch (error) {
      const message = error instanceof Error ? error.message : "Cards lookup failed";
      return asJsonResponse(500, { error: message });
    }
  }
  return asJsonResponse(status, body);
}
var vercelCardsApi = Object.assign(handler, { fetch: GET });
var vercelCards_default = vercelCardsApi;
export {
  GET,
  vercelCards_default as default,
  handler
};
